code='''from collections import deque
from math import gcd
from functools import reduce

def _components(points):
    points=set(points); out=[]
    while points:
        start=min(points); points.remove(start); q=[start]; comp={start}
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in points: points.remove(p); comp.add(p); q.append(p)
        out.append(comp)
    return out

def _orientations(shape):
    variants=set()
    for flip in (1,-1):
        for rot in range(4):
            pts=[]
            for r,c in shape:
                x,y=r,flip*c
                for _ in range(rot): x,y=y,-x
                pts.append((x,y))
            mr=min(x for x,y in pts); mc=min(y for x,y in pts)
            variants.add(tuple(sorted((x-mr,y-mc) for x,y in pts)))
    return sorted(variants, key=lambda s:(max(r for r,c in s)+1,max(c for r,c in s)+1,s))

def transform(grid):
    a=[list(row) for row in grid]; h=len(a); w=len(a[0])
    ink=[(r,c) for r in range(h) for c in range(w) if a[r][c]==8]
    if not ink: return a
    # The colored key is the non-8, non-background material outside the large 8 figure.
    key=[(r,c,a[r][c]) for r in range(h) for c in range(w) if a[r][c] not in (0,8)]
    if not key: return a
    # Determine the enlargement factor from the repeated solid 8-block runs.
    runs=[]
    for r in range(h):
        c=0
        while c<w:
            if a[r][c]!=8: c+=1; continue
            s=c
            while c<w and a[r][c]==8: c+=1
            runs.append(c-s)
    for c in range(w):
        r=0
        while r<h:
            if a[r][c]!=8: r+=1; continue
            s=r
            while r<h and a[r][c]==8: r+=1
            runs.append(r-s)
    k=reduce(gcd,runs)
    if k<1: return a
    # Every complete k-by-k square of the large figure is one abstract cell.
    r0=min(r for r,c in ink); c0=min(c for r,c in ink)
    cells=set()
    for r in range(r0,h-k+1,k):
        for c in range(c0,w-k+1,k):
            if all(a[y][x]==8 for y in range(r,r+k) for x in range(c,c+k)):
                cells.add(((r-r0)//k,(c-c0)//k))
    if not cells: return a
    # Key colored components are the tile shapes and their colors.
    bycolor={}
    for r,c,col in key: bycolor.setdefault(col,set()).add((r,c))
    pieces=[]
    for col,pts in bycolor.items():
        for comp in _components(pts):
            mr=min(r for r,c in comp); mc=min(c for r,c in comp)
            pieces.append((min(comp),col,tuple(sorted((r-mr,c-mc) for r,c in comp))))
    pieces.sort(key=lambda x:x[0])
    total=sum(len(p[2]) for p in pieces)
    if len(cells)%total: return a
    copies=len(cells)//total
    # Each key motif is reused uniformly when the large figure contains repeated copies.
    inventory=[(col,shape,copies) for _,col,shape in pieces]
    variants=[_orientations(shape) for col,shape,n in inventory]
    left=set(cells); assigned={}
    def solve():
        if not left: return all(n==0 for _,_,n in inventory)
        cell=min(left)
        for i,(col,shape,n) in enumerate(inventory):
            if n<=0: continue
            for orient in variants[i]:
                for anchor in orient:
                    dr=cell[0]-anchor[0]; dc=cell[1]-anchor[1]
                    placed={(dr+r,dc+c) for r,c in orient}
                    if cell not in placed or not placed<=left: continue
                    inventory[i]=(col,shape,n-1)
                    left.difference_update(placed)
                    for p in placed: assigned[p]=col
                    if solve(): return True
                    for p in placed: assigned.pop(p,None)
                    left.update(placed)
                    inventory[i]=(col,shape,n)
        return False
    if not solve(): return a
    for (rr,cc),col in assigned.items():
        y0=r0+rr*k; x0=c0+cc*k
        for y in range(y0,y0+k):
            for x in range(x0,x0+k):
                if a[y][x]==8: a[y][x]=col
    return a
'''
